-- процедура архивации старых заказов
CREATE OR REPLACE PROCEDURE archive_old_orders(cutoff_date DATE)
LANGUAGE plpgsql AS $$
DECLARE
  batch_size INT := 1000;
  rows_moved INT;
BEGIN
  LOOP
    INSERT INTO orders_archive
    SELECT * FROM orders
    WHERE created_at < cutoff_date
    LIMIT batch_size;

    GET DIAGNOSTICS rows_moved = ROW_COUNT;

    DELETE FROM orders
    WHERE id IN (
      SELECT id FROM orders
      WHERE created_at < cutoff_date
      LIMIT batch_size
    );

    COMMIT; -- фиксируем каждую порцию
    EXIT WHEN rows_moved < batch_size;
  END LOOP;
END;
$$;

CALL archive_old_orders('2024-01-01');

-- trigger-функция: автообновление updated_at
CREATE OR REPLACE FUNCTION set_updated_at()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := NOW();
  RETURN NEW;
END;
$$;

CREATE TRIGGER trg_users_updated_at
  BEFORE UPDATE ON users
  FOR EACH ROW
  EXECUTE FUNCTION set_updated_at();

-- trigger-функция: аудит изменений зарплаты
CREATE OR REPLACE FUNCTION audit_salary_change()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.salary <> NEW.salary THEN
    INSERT INTO salary_audit (employee_id, old_salary, new_salary, changed_at)
    VALUES (OLD.id, OLD.salary, NEW.salary, NOW());
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER trg_salary_audit
  AFTER UPDATE OF salary ON employees
  FOR EACH ROW
  EXECUTE FUNCTION audit_salary_change();

