SELECT trigger_name, event_manipulation, action_timing
FROM information_schema.triggers
WHERE event_object_table = 'employees';

-- удалить триггер:
DROP TRIGGER IF EXISTS trg_salary_audit ON employees;

-- данные
CREATE TABLE events (
  id   SERIAL PRIMARY KEY,
  data JSONB
);
INSERT INTO events (data) VALUES
  ('{"type":"click","user":{"id":1,"name":"Ivan"},"tags":["web","mobile"]}');

-- получить значения
SELECT data -> 'type'            -- "click" (JSONB)
     , data ->> 'type'           -- click   (TEXT)
     , data -> 'user' ->> 'name' -- Ivan
     , data #>> '{user,name}'    -- Ivan (через путь)
FROM events;

-- поиск по содержимому (GIN-индекс!)
SELECT * FROM events
WHERE data @> '{"type":"click"}';

-- проверить ключ
SELECT * FROM events WHERE data ? 'tags';

-- изменить вложенное поле
UPDATE events
SET data = jsonb_set(data, '{user,name}', '"Petr"')
WHERE id = 1;

-- GIN-индекс для @> поиска
CREATE INDEX idx_events_data ON events USING GIN (data);

-- собрать объект из запроса
SELECT jsonb_agg(data) FROM events WHERE data @> '{"type":"click"}';

CREATE TABLE posts (
  id    SERIAL PRIMARY KEY,
  title TEXT,
  tags  TEXT[]
);
INSERT INTO posts (title, tags) VALUES
  ('Node.js tips', ARRAY['nodejs','javascript','backend']),
  ('SQL basics',   '{"sql","postgresql","database"}');

-- поиск по тегу
SELECT * FROM posts WHERE 'nodejs' = ANY(tags);

-- посты с обоими тегами
SELECT * FROM posts WHERE tags @> ARRAY['sql','postgresql'];

-- посты с хотя бы одним из тегов
SELECT * FROM posts WHERE tags && ARRAY['nodejs','sql'];

-- раскрыть массив в строки
SELECT id, unnest(tags) AS tag FROM posts;

-- собрать теги в массив
SELECT array_agg(DISTINCT tag ORDER BY tag)
FROM posts, unnest(tags) AS t(tag);

-- GIN-индекс
CREATE INDEX idx_posts_tags ON posts USING GIN (tags);

-- базовый поиск
SELECT title FROM articles
WHERE to_tsvector('russian', content)
   @@ to_tsquery('russian', 'postgresql & триггер');

-- plainto_tsquery (удобнее)
SELECT title FROM articles
WHERE to_tsvector('english', content)
   @@ plainto_tsquery('english', 'trigger function');

-- с релевантностью
SELECT title,
  ts_rank(
    to_tsvector('english', content),
    to_tsquery('english', 'index & performance')
  ) AS rank
FROM articles
WHERE to_tsvector('english', content)
   @@ to_tsquery('english', 'index & performance')
ORDER BY rank DESC;

-- подсветка совпадений
SELECT ts_headline('english', content,
  to_tsquery('index'))
FROM articles LIMIT 5;

-- производительный вариант: сохранить вектор
ALTER TABLE articles ADD COLUMN search_vec TSVECTOR;
UPDATE articles
  SET search_vec = to_tsvector('english', title || ' ' || content);
CREATE INDEX idx_articles_fts ON articles USING GIN (search_vec);

SELECT title FROM articles
WHERE search_vec @@ to_tsquery('index & performance');

-- пользователь видит только свои записи
