  id         BIGSERIAL,
  event      TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
) PARTITION BY RANGE (created_at);

CREATE TABLE logs_2024
  PARTITION OF logs
  FOR VALUES FROM ('2024-01-01') TO ('2025-01-01');

CREATE TABLE logs_2025
  PARTITION OF logs
  FOR VALUES FROM ('2025-01-01') TO ('2026-01-01');

